impl Solution {
    pub fn max_k_segments_sum(nums: Vec<i64>, m: usize, k: usize) -> i128 {
        let n = nums.len();
        let len = n - m + 1; // number of possible start positions
        // prefix sums
        let mut pref = vec![0i128; n + 1];
        for i in 0..n {
            pref[i + 1] = pref[i] + nums[i] as i128;
        }
        // segment sums
        let mut seg = vec![0i128; len];
        for s in 0..len {
            seg[s] = pref[s + m] - pref[s];
        }
        // dp[j][s] = max sum using j segments considering starts up to s
        let mut dp = vec![vec![0i128; len]; k + 1];
        for j in 1..=k {
            for s in 0..len {
                let take = seg[s] + if s >= m { dp[j - 1][s - m] } else { 0 };
                let skip = if s > 0 { dp[j][s - 1] } else { 0 };
                dp[j][s] = if take > skip { take } else { skip };
            }
        }
        dp[k][len - 1]
    }
}

